SELECT o.order_id, c.name FROM dbo.Orders o INNER JOIN dbo.Customers c ON c.customer_id = o.customer_id;
SELECT o.order_id, c.name FROM dbo.Orders o JOIN dbo.Customers c ON c.customer_id = o.customer_id;
SELECT o.order_id, c.name FROM dbo.Orders o LEFT OUTER JOIN dbo.Customers c ON c.customer_id = o.customer_id;
SELECT o.order_id, c.name FROM dbo.Orders o RIGHT JOIN dbo.Customers c ON c.customer_id = o.customer_id;
SELECT o.order_id, c.name FROM dbo.Orders o FULL OUTER JOIN dbo.Customers c ON c.customer_id = o.customer_id;
SELECT o.order_id, r.region_name FROM dbo.Orders o CROSS JOIN dbo.Regions r;
SELECT o.order_id, r.region_name FROM dbo.Orders o, dbo.Regions r WHERE o.region_id = r.region_id;
SELECT c.name, x.order_id FROM dbo.Customers c CROSS APPLY (SELECT TOP (3) order_id FROM dbo.Orders o WHERE o.customer_id = c.customer_id ORDER BY o.order_date DESC) AS x;
SELECT c.name, x.last_order FROM dbo.Customers c OUTER APPLY (SELECT MAX(order_date) AS last_order FROM dbo.Orders o WHERE o.customer_id = c.customer_id) x;
SELECT c.name, f.total FROM dbo.Customers c CROSS APPLY dbo.fn_customer_totals(c.customer_id) AS f;
SELECT c.name, s.value FROM dbo.Customers c CROSS APPLY STRING_SPLIT(c.tags, ',') AS s;
SELECT c.name, s.value, s.ordinal FROM dbo.Customers c CROSS APPLY STRING_SPLIT(c.tags, ',', 1) AS s;
SELECT o.order_id, l.product_id, p.name FROM dbo.Orders o JOIN dbo.OrderLines l ON l.order_id = o.order_id LEFT JOIN dbo.Products p ON p.product_id = l.product_id AND p.active = 1;
SELECT o.order_id FROM dbo.Orders o INNER HASH JOIN dbo.Customers c ON c.customer_id = o.customer_id;
SELECT o.order_id FROM dbo.Orders o LEFT MERGE JOIN dbo.Customers c ON c.customer_id = o.customer_id;
SELECT o.order_id FROM dbo.Orders o INNER LOOP JOIN dbo.Customers c ON c.customer_id = o.customer_id;
SELECT a.id FROM dbo.A a JOIN (dbo.B b JOIN dbo.C c ON c.id = b.c_id) ON b.a_id = a.id;
SELECT e.name, m.name AS manager FROM hr.Employees e LEFT JOIN hr.Employees m ON m.employee_id = e.manager_id;
SELECT v.k, v.label FROM (VALUES (1, 'one'), (2, 'two'), (3, 'three')) AS v (k, label);
SELECT t.id FROM dbo.T1 t JOIN dbo.T2 u ON t.id = u.id AND t.dt >= u.start_dt AND t.dt < ISNULL(u.end_dt, '9999-12-31');
SELECT * FROM OPENQUERY(remote_srv, 'SELECT id, name FROM inv.items');
SELECT * FROM OPENROWSET(BULK 'C:\data\items.csv', FORMAT = 'CSV', FIRSTROW = 2, FORMATFILE = 'C:\data\items.fmt') AS rows;
SELECT * FROM OPENROWSET(BULK N'C:\data\doc.json', SINGLE_CLOB) AS j;
SELECT * FROM OPENDATASOURCE('MSOLEDBSQL', 'Server=srv2;Trusted_Connection=yes;').inventory.dbo.items;
